sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {

    var result = [];

    var gr = new GlideRecord('incident');

    if (!gr.isValid()) {
        response.setStatus(500);
        response.setBody({
            success: false,
            error: 'Incident table is invalid'
        });
        return;
    }

    gr.orderByDesc('sys_created_on');
    gr.query();

    while (gr.next()) {

        result.push({
            sys_id: gr.getUniqueValue(),
            number: gr.getValue('number'),
            short_description: gr.getValue('short_description'),
            description: gr.getValue('description'),
            category: gr.getValue('category'),
            subcategory: gr.getValue('subcategory'),
            priority: gr.getValue('priority'),
            state: gr.getDisplayValue('state'),
            assignment_group: gr.getDisplayValue('assignment_group'),
            assigned_to: gr.getDisplayValue('assigned_to'),
            opened_at: gr.getValue('opened_at'),
            updated_at: gr.getValue('sys_updated_on')
        });
    }

    response.setStatus(200);

    response.setBody({
        success: true,
        count: result.length,
        requests: result
    });

})(request, response);
